-- Titre professionnel et biographie (badge digital) de Wiame Lagha et Mohamed Haddad.
update public.equipe_membres set
  titre = 'Jeune diplômée en génie industriel',
  biographie = $bio$Diplômée en Génie Industriel de l’Université Mundiapolis, forte d'expériences riches en milieu industriel chez OCP et Shell & Vivo Lubricants Maroc.
Grâce à une formation axée sur la gestion de projets, la planification et l'optimisation des processus, je mets mes compétences méthodologiques et organisationnelles au service de la conception et du pilotage d'événements. Mon parcours combine rigueur analytique, coordination d'équipes et maîtrise des outils de suivi pour garantir une gestion fluide, le respect des objectifs et la réussite globale des projets événementiels.$bio$
where dossier = 'INT2026-011';

update public.equipe_membres set
  titre = 'Ingénieur d''État en Réseaux et Cybersécurité',
  biographie = $bio$Diplômé en tant qu'Ingénieur d'État en Réseaux et Cybersécurité de l'ENSA Khouribga, fort d'une expérience de déploiement d'architectures de sécurité avancées à l'UM6P.
Grâce à une formation axée sur l'ingénierie réseau, les tests d'intrusion et la défense en profondeur, je mets mes compétences techniques au service de la conception d'environnements cyberrange et de solutions Zero Trust. Mon parcours combine rigueur analytique, veille technologique et maîtrise des environnements virtualisés (Proxmox, pfSense, Docker) pour optimiser la protection des systèmes d'information et la réussite des projets de cybersécurité.$bio$
where dossier = 'INT2026-012';
